from collections import deque

def rolling_max(numbers: List[int]) -> List[int]:
    if not numbers:
        return []

    rolling_max_list = []
    window_indices = deque()

    for i, num in enumerate(numbers):
        while window_indices and window_indices[0] < i - len(numbers) + 1:
            window_indices.popleft()

        while window_indices and numbers[window_indices[-1]] < num:
            window_indices.pop()

        window_indices.append(i)

        if i >= len(numbers) - 1:
            rolling_max_list.append(numbers[window_indices[0]])

    return rolling_max_list

