import math

def closest_integer(value):
    num = float(value)
    floor_num = math.floor(num)
    ceil_num = math.ceil(num)

    diff_floor = abs(num - floor_num)
    diff_ceil = abs(num - ceil_num)

    if diff_floor < diff_ceil:
        return int(floor_num)
    elif diff_ceil < diff_floor:
        return int(ceil_num)
    else:
        if num >= 0:
            return int(ceil_num)
        else:
            return int(floor_num)

